let stored=[];try{const value=JSON.parse(localStorage.getItem('sahra-saved')||'[]');if(Array.isArray(value))stored=value.filter(id=>dishes.some(d=>d.id===id))}catch{}
const saved=new Set(stored);const state={cat:'all',query:'',veg:false,saved:false,sort:'recommended'};
const $=selector=>document.querySelector(selector);const modal=$('#dish-dialog');let activeDish=null;let opener=null;let toastTimer;
function announce(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2800)}
function persist(){try{localStorage.setItem('sahra-saved',JSON.stringify([...saved]))}catch{}$('#saved-count').textContent=saved.size;$('#saved-toggle').setAttribute('aria-label',`Saved dishes, ${saved.size} saved`)}
function filteredDishes(){const q=state.query.trim().toLocaleLowerCase();const items=dishes.filter(d=>(state.cat==='all'||d.cat===state.cat)&&(!state.veg||d.veg)&&(!state.saved||saved.has(d.id))&&(!q||`${d.name} ${d.ar} ${d.desc} ${d.ingredients}`.toLocaleLowerCase().includes(q)));if(state.sort==='price-up')items.sort((a,b)=>a.price-b.price);if(state.sort==='price-down')items.sort((a,b)=>b.price-a.price);if(state.sort==='name')items.sort((a,b)=>a.name.localeCompare(b.name));return items}
function render(){const items=filteredDishes();$('#menu-sections').innerHTML=menuTemplates.sections(items,saved);$('#result-count').textContent=`${items.length} ${items.length===1?'dish':'dishes'}${state.saved?' · Your saved favourites':''}`;$('.empty').hidden=items.length>0;$('#empty-title').textContent=state.saved?'Your favourites start here.':'No matches on this menu.';$('#empty-copy').textContent=state.saved?'Tap the heart on a dish to save it for later.':'Try a different ingredient, or clear your filters to explore everything.';$('#reset').hidden=state.cat==='all'&&!state.query.trim()&&!state.veg&&!state.saved&&state.sort==='recommended';document.querySelectorAll('[data-cat]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.cat===state.cat)));$('#category-select').value=state.cat;$('#sort').value=state.sort;$('#veg').setAttribute('aria-pressed',String(state.veg));$('#saved-toggle').setAttribute('aria-pressed',String(state.saved));persist();window.sahraMotion?.refresh()}
function updateDialogSave(){const button=$('#dialog-save');if(!button||!activeDish)return;button.textContent=saved.has(activeDish.id)?'♥ Saved to your favourites':'♡ Save this dish';button.setAttribute('aria-pressed',String(saved.has(activeDish.id)))}
function toggleSave(id){const dish=dishes.find(d=>d.id===id);if(!dish)return;const adding=!saved.has(id);adding?saved.add(id):saved.delete(id);persist();if(state.saved)render();else document.querySelectorAll(`[data-save="${id}"]`).forEach(button=>{if(button.id==='dialog-save')return;button.innerHTML=`<span aria-hidden="true">${adding?'♥':'♡'}</span>`;button.setAttribute('aria-pressed',String(adding));button.setAttribute('aria-label',`${adding?'Unsave':'Save'} ${dish.name}`)});updateDialogSave();if(adding)window.sahraMotion?.heart(id);announce(`${dish.name} ${adding?'saved to':'removed from'} your favourites.`)}
function openDish(id){const dish=dishes.find(d=>d.id===id);if(!dish)return;activeDish=dish;opener=document.querySelector(`[data-dish="${id}"]`)||document.activeElement;const e=menuTemplates.escape;$('#dialog-content').innerHTML=`<img class="dialog-photo" src="assets/${dish.img}.jpg" width="1024" height="1024" alt="${e(dish.name)}"><div class="dialog-body"><span class="dialog-label">SAHRA / ${categories.find(c=>c.id===dish.cat).name.toUpperCase()}</span><h2 id="dialog-title" tabindex="-1">${e(dish.name)}</h2><span class="arabic-name" lang="ar" dir="rtl">${dish.ar}</span><p>${e(dish.desc)}</p><div class="dialog-columns"><div><h3>What goes in</h3><p>${e(dish.ingredients)}</p></div><div><h3>Allergen notes</h3><p>${e(dish.allergens)}</p></div></div><div class="dialog-actions"><span class="detail-price">${menuTemplates.money(dish.price)}</span><button id="dialog-save" class="dialog-save" data-save="${dish.id}"></button></div><p class="dialog-note">Please let the kitchen know about any allergies before ordering.</p></div>`;updateDialogSave();modal.showModal();document.body.classList.add('dialog-open');modal.scrollTop=0;$('#dialog-title').focus({preventScroll:true});window.sahraMotion?.openDialog()}
modal.addEventListener('close',()=>{document.body.classList.remove('dialog-open');if(opener?.isConnected&&opener!==document.body)opener.focus({preventScroll:true});else if(activeDish){const target=document.querySelector(`[data-dish="${activeDish.id}"]`)||$('#saved-toggle');target?.focus({preventScroll:true})}});
function reset(){Object.assign(state,{cat:'all',query:'',veg:false,saved:false,sort:'recommended'});$('#search').value='';render()}
function chooseCategory(id){state.cat=categories.some(c=>c.id===id)?id:'all';render();$('#menu').scrollIntoView({block:'start'});document.querySelector(`[data-cat="${state.cat}"]`)?.scrollIntoView({block:'nearest',inline:'nearest'})}
const menuCategories=[{id:'all',name:'The whole menu'},...categories];$('#categories').innerHTML=menuCategories.map(category=>`<button data-cat="${category.id}" aria-pressed="${category.id==='all'}">${category.name}<small>${category.id==='all'?dishes.length:dishes.filter(d=>d.cat===category.id).length}</small></button>`).join('');$('#category-select').innerHTML=menuCategories.map(c=>`<option value="${c.id}">${c.name}</option>`).join('');
document.addEventListener('click',event=>{const save=event.target.closest('[data-save]');if(save){toggleSave(save.dataset.save);return}const dish=event.target.closest('[data-dish]');if(dish){openDish(dish.dataset.dish);return}const category=event.target.closest('[data-cat]');if(category)chooseCategory(category.dataset.cat)});
$('#search').addEventListener('input',event=>{state.query=event.target.value;render()});$('#category-select').addEventListener('change',event=>chooseCategory(event.target.value));$('#sort').addEventListener('change',event=>{state.sort=event.target.value;render()});$('#veg').addEventListener('click',()=>{state.veg=!state.veg;render()});$('#saved-toggle').addEventListener('click',()=>{state.saved=!state.saved;render();$('#menu').scrollIntoView({block:'start'})});$('#reset').addEventListener('click',reset);$('#empty-reset').addEventListener('click',reset);$('#print').addEventListener('click',()=>window.print());window.addEventListener('beforeprint',()=>document.querySelectorAll('img[loading]').forEach(image=>image.loading='eager'));
$('#share').addEventListener('click',async()=>{const url=new URL('https://sahra-kitchen-menu.alaasaasouh2.chatgpt.site/');if(state.cat!=='all')url.searchParams.set('category',state.cat);url.hash='menu';try{if(navigator.share){await navigator.share({title:'Sahra — Yemeni Kitchen',text:'A table full of favourites.',url:url.href})}else if(navigator.clipboard){await navigator.clipboard.writeText(url.href);announce('Menu link copied. Share something delicious.')}else announce('Share this menu using the address in your browser.')}catch(error){if(error.name!=='AbortError')announce('Share this menu using the address in your browser.')}});
$('.close').addEventListener('click',()=>window.sahraMotion?.closeDialog()||modal.close());modal.addEventListener('click',event=>{if(event.target!==modal)return;const rect=modal.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom){if(window.sahraMotion)window.sahraMotion.closeDialog();else modal.close()}});document.addEventListener('keydown',event=>{if(event.key==='/'&&!modal.open&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){event.preventDefault();$('#search').focus()}});
const incomingCategory=new URLSearchParams(location.search).get('category');if(categories.some(c=>c.id===incomingCategory))state.cat=incomingCategory;render();
